import type { ReactNode } from 'react';
import './navigation-sidebar.css';

type Item = { id: string; label: string; icon?: ReactNode; disabled?: boolean };
type Section = { id: string; label: string; items: Item[] };
type Props = { sections: Section[]; selectedId: string; onSelect: (id: string) => void; summary: ReactNode; footerActions: ReactNode };

export function NavigationSidebar({ sections, selectedId, onSelect, summary, footerActions }: Props) {
  return <div className="sidebar">
    <div className="sidebarSections">{sections.map(section => <section className="navSection" aria-labelledby={`nav-${section.id}`} key={section.id}>
      <h2 id={`nav-${section.id}`}>{section.label}</h2>
      <ul>{section.items.map(item => <li key={item.id}><button type="button" className="navRow" aria-current={selectedId === item.id ? 'page' : undefined} disabled={item.disabled} onClick={() => onSelect(item.id)}><span className="navIcon" aria-hidden="true">{item.icon}</span><span>{item.label}</span></button></li>)}</ul>
    </section>)}</div>
    <section className="workspaceSummary" aria-label="Workspace summary">{summary}</section>
    <div className="sidebarFooter" aria-label="Workspace actions">{footerActions}</div>
  </div>;
}

