.sidebar { --gutter: .75rem; block-size: 100%; min-block-size: 0; display: flex; flex-direction: column; padding: var(--gutter); color: #25252b; background: #f7f7f9; }
.sidebarSections { overflow-y: auto; min-block-size: 0; }
.navSection + .navSection { margin-block-start: 1rem; }
.navSection h2 { margin: 0 0 .375rem; padding-inline: .625rem; color: #696974; font-size: .6875rem; line-height: 1.5; letter-spacing: .06em; text-transform: uppercase; }
.navSection ul { margin: 0; padding: 0; list-style: none; }
.navRow { inline-size: 100%; min-block-size: 2rem; display: grid; grid-template-columns: 1.25rem minmax(0, 1fr); align-items: center; gap: .5rem; padding: .375rem .625rem; border: 0; border-radius: .375rem; background: transparent; color: inherit; font: inherit; text-align: start; cursor: pointer; }
.navIcon { inline-size: 1.25rem; block-size: 1.25rem; display: grid; place-items: center; }
.navIcon:empty::after { content: ''; }
.navRow:hover:not(:disabled) { background: #ebebef; }
.navRow[aria-current='page'] { background: #deddfb; color: #29237e; font-weight: 600; }
.navRow:disabled { color: #92929c; cursor: not-allowed; }
.navRow:focus-visible, .sidebarFooter :is(button,a):focus-visible { outline: 2px solid #4f46e5; outline-offset: 1px; }
.workspaceSummary { flex: none; margin-block-start: .75rem; padding: .75rem; border: 1px solid #ddddE3; border-radius: .5rem; background: #fff; }
.sidebarFooter { flex: none; display: flex; gap: .25rem; align-items: center; margin-block-start: .5rem; padding-block-start: .5rem; border-block-start: 1px solid #dddde3; }
.sidebarFooter :is(button,a) { min-block-size: 1.75rem; padding: .25rem .5rem; }
